// Os 5 superpoderes de unsafe
// 1. Dereferenciar raw pointer (*const T, *mut T)
// 2. Chamar fn marcada unsafe
// 3. Acessar ou modificar static mut
// 4. Implementar unsafe trait (Send, Sync em tipos custom)
// 5. Acessar campo de union

let mut x = 10;
let p: *mut i32 = &mut x;
unsafe {
    *p = 42;           // deref de raw pointer
}
assert_eq!(x, 42);

/// Lê um u32 pequeno-endian de um ponteiro
///
/// # Safety
/// - `ptr` deve ser válido para leitura de 4 bytes
/// - `ptr` deve estar alinhado em 4 bytes
/// - Os 4 bytes não podem ser mutados por outra thread durante a leitura
unsafe fn read_u32_le(ptr: *const u8) -> u32 {
    let bytes = std::ptr::read_unaligned(ptr as *const [u8; 4]);
    u32::from_le_bytes(bytes)
}

fn caller() {
    let buf = [0x01, 0x00, 0x00, 0x00];
    // SAFETY: buf é válido por 4 bytes, vive pelo escopo, não há outra thread
    let v = unsafe { read_u32_le(buf.as_ptr()) };
    assert_eq!(v, 1);
}

// Chamar libc do sistema
extern "C" {
    fn abs(input: i32) -> i32;
}

fn main() {
    unsafe {
        println!("abs(-5) = {}", abs(-5));
    }
}

// Expor uma função Rust com ABI C (consumível de C, Python, Node...)
#[no_mangle]
pub extern "C" fn fibonacci(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => {
            let (mut a, mut b) = (0u64, 1u64);
            for _ in 2..=n { let t = a + b; a = b; b = t; }
            b
        }
    }
}

use pyo3::prelude::*;

#[pyfunction]
fn tokenize(text: &str) -> Vec<String> {
    text.split_whitespace().map(String::from).collect()
}

#[pymodule]
fn fast_tokenizer(_py: Python, m: &PyModule) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(tokenize, m)?)?;
    Ok(())
}

// build com maturin: maturin develop
// no Python:
// >>> import fast_tokenizer
// >>> fast_tokenizer.tokenize("olá mundo")
// ['olá', 'mundo']

use napi_derive::napi;

#[napi]
pub fn sum(a: i32, b: i32) -> i32 { a + b }

#[napi]
async fn fetch_status(url: String) -> napi::Result<String> {
    let r = reqwest::get(&url).await.map_err(|e| napi::Error::from_reason(e.to_string()))?;
    Ok(r.status().to_string())
}

